       @Override
       public void afterCheckFile(Context context) {
           if (context instanceof XmlContext) {
               File file = context.file;
               int[] counts = xmlFileCounts.get(file);
               if (counts != null) {
                   int always = counts[0];
                   int ifRoom = counts[1];
