                   ctx.report(ISSUE, ctx.getLocation(elem),
                       "Prefer `SHOW_AS_ACTION_IF_ROOM` instead of `SHOW_AS_ACTION_ALWAYS`");
               }
           }
           xmlFileCounts = null;
           javaAlwaysContexts = null;
           javaAlwaysElements = null;
